// World land outlines for the fleet-snapshot renderer.
//
// GENERATED FILE — do not hand-edit. Source: Natural Earth 1:50m land
// (public domain) via the world-atlas@2.0.2 npm package; outer rings only,
// Douglas-Peucker simplified at 0.008°, quantized to 0.01°, delta + zigzag
// varint encoded, base64. 1:50m (not 1:110m) because the fleet calls at small
// islands (Society Islands, Lesser Antilles) that 1:110m erases entirely.
// Regenerate with scripts in the repo history of this file's introducing PR.

const PACKED =
  '' +
  '' +
  '' +
  '' +
  '' +
  '' +
  '' +
  '' +
  '' +
  '' +
  '' +
  '' +
  '' +
  '' +
  '' +
  '' +
  '' +
  '' +
  '' +
  '' +
  '' +
  '' +
  '' +
  '' +
  '' +
  '' +
  '' +
  '' +
  '' +
  '' +
  '' +
  '' +
  '' +
  '' +
  '' +
  '';

let cache: Float32Array[] | null = null;

// Decode to one Float32Array per ring, flat [lon0, lat0, lon1, lat1, ...] in
// degrees. Decoded once and cached (~60k points).
export function landRings(): Float32Array[] {
  if (cache) return cache;
  const bin = atob(PACKED);
  const n = bin.length;
  let pos = 0;
  const varint = (): number => {
    let shift = 1;
    let result = 0;
    for (;;) {
      const b = bin.charCodeAt(pos++);
      result += (b & 127) * shift;
      if ((b & 128) === 0) return result;
      shift *= 128;
    }
  };
  const unzz = (v: number): number => (v % 2 === 1 ? -(v + 1) / 2 : v / 2);
  const ringCount = varint();
  const rings: Float32Array[] = [];
  for (let r = 0; r < ringCount && pos < n; r++) {
    const count = varint();
    const ring = new Float32Array(count * 2);
    let x = 0;
    let y = 0;
    for (let i = 0; i < count; i++) {
      x += unzz(varint());
      y += unzz(varint());
      ring[i * 2] = x / 100;
      ring[i * 2 + 1] = y / 100;
    }
    rings.push(ring);
  }
  cache = rings;
  return rings;
}
